/**
 * Proves the summarisation strategy end-to-end: with MAX_WINDOW_MESSAGES=4,
 * early facts fall out of the raw window and must survive via the running
 * summary generated by the LLM.
 *
 * Run:  $env:MAX_WINDOW_MESSAGES='4'; node test/run-summary.mjs
 */
import { spawn } from "node:child_process";
import { setTimeout as sleep } from "node:timers/promises";
import { fileURLToPath } from "node:url";
import path from "node:path";

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const PORT = Number(process.env.TEST_PORT) || 3112;
const BASE = `http://localhost:${PORT}`;

const server = spawn(process.execPath, ["server.js"], {
  cwd: ROOT,
  env: { ...process.env, PORT: String(PORT), MAX_WINDOW_MESSAGES: process.env.MAX_WINDOW_MESSAGES || "4" },
  stdio: "ignore",
});

let up = false;
for (let i = 0; i < 40 && !up; i++) {
  await sleep(500);
  try { up = (await fetch(`${BASE}/api/health`)).ok; } catch { /* wait */ }
}
if (!up) { console.error("server not healthy"); server.kill(); process.exit(1); }

const cid = crypto.randomUUID();
const chat = async (message) => {
  const r = await fetch(`${BASE}/api/chat`, {
    method: "POST", headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ conversationId: cid, message }),
  });
  return r.json();
};

const script = [
  "Remember this: my home town is Pune and my secret code word is mango-lantern.",
  "What is the tallest mountain in the world?",
  "Thanks. Now tell me a quick joke about programmers.",
  "That was funny. What is the boiling point of water at sea level?",
  "Good. Final question — what is my home town and my secret code word?",
];

console.log(`window=${process.env.MAX_WINDOW_MESSAGES || 4} msgs, conversation=${cid}\n`);
for (const msg of script) {
  console.log(`You    > ${msg}`);
  const d = await chat(msg);
  if (d.error) { console.error("✗", d.error); server.kill(); process.exit(1); }
  console.log(`Kryptix> ${d.reply}`);
  console.log(`         [window=${d.meta.windowMessages}/${d.meta.totalMessages} summary=${d.meta.summaryActive ? "ACTIVE" : "inactive"}${d.meta.summaryJustUpdated ? " ⟳just updated" : ""}]\n`);
}

const h = await (await fetch(`${BASE}/api/history?conversationId=${cid}`)).json();
console.log("── Stored running summary on the server ──\n" + (h.summary ?? "(none)"));
server.kill();
await sleep(200);
console.log("\nIf the last reply recalls Pune + mango-lantern AFTER those messages were truncated out of the window, the summarisation strategy is proven.");
